import { createPinia } from 'pinia';
import { createApp } from 'vue';
import App from './App.vue';
import { Schema } from '../修仙状态栏/schema';

let openingFrameObserver: ResizeObserver | null = null;

function ensureOpeningStatData() {
  const option = { type: 'message', message_id: getCurrentMessageId() } as const;
  const variables = getVariables(option);
  const stat_data = _.get(variables, 'stat_data', {});
  const result = Schema.safeParse(stat_data);
  if (!result.success) {
    console.warn('[开场] 当前楼层 stat_data 校验失败，使用默认开场变量继续渲染', result.error);
    _.set(variables, 'stat_data', Schema.parse({}));
    replaceVariables(variables, option);
    return;
  }
  if (!_.isEqual(stat_data, result.data)) {
    _.set(variables, 'stat_data', result.data);
    replaceVariables(variables, option);
  }
}

function adaptMobileOpeningFrame() {
  if (window.parent === window || window.parent.innerWidth >= 600) return;
  const frame = window.frameElement as HTMLElement | null;
  if (!frame) return;

  const host = frame.parentElement;
  const container = host?.parentElement;

  frame.style.setProperty('display', 'block', 'important');
  frame.style.removeProperty('min-height');
  frame.style.setProperty('margin', '0 auto', 'important');
  frame.style.removeProperty('margin-left');
  frame.style.removeProperty('transform');
  frame.style.setProperty('border', '0', 'important');
  frame.style.setProperty('box-sizing', 'border-box', 'important');

  if (host) {
    host.style.setProperty('margin', '0 auto', 'important');
    host.style.removeProperty('margin-left');
    host.style.removeProperty('transform');
    host.style.removeProperty('overflow');
    host.style.setProperty('overflow-x', 'hidden', 'important');
    host.style.setProperty('overflow-y', 'visible', 'important');
    host.style.setProperty('box-sizing', 'border-box', 'important');
  }

  const syncWidth = () => {
    const viewportWidth = Math.max(1, window.parent.innerWidth - 24);
    let containerWidth = viewportWidth;
    if (container) {
      const style = window.parent.getComputedStyle(container);
      const horizontalPadding =
        (Number.parseFloat(style.paddingLeft) || 0) + (Number.parseFloat(style.paddingRight) || 0);
      containerWidth = Math.max(1, container.clientWidth - horizontalPadding);
    }
    // 向下取整并预留 2px，规避移动端子像素舍入把右边框推出消息容器。
    const frameWidth = Math.max(1, Math.floor(Math.min(viewportWidth, containerWidth)) - 2);
    frame.style.setProperty('width', `${frameWidth}px`, 'important');
    frame.style.setProperty('max-width', '100%', 'important');
    if (host) {
      host.style.setProperty('width', `${frameWidth}px`, 'important');
      host.style.setProperty('max-width', '100%', 'important');
    }
  };

  const syncHeight = () => {
    syncWidth();
    const activeRoot = document.querySelector('.creator, .start-screen, .story-screen') as HTMLElement | null;
    const activeHeight = activeRoot ? activeRoot.getBoundingClientRect().height : 0;
    const height = Math.ceil(Math.max(activeHeight, document.documentElement.scrollHeight, document.body.scrollHeight));
    frame.style.setProperty('height', `${height}px`, 'important');
  };

  syncHeight();
  openingFrameObserver?.disconnect();
  openingFrameObserver = new ResizeObserver(syncHeight);
  openingFrameObserver.observe(document.documentElement);
  openingFrameObserver.observe(document.body);
  window.addEventListener('resize', syncHeight, { passive: true });
  $(window).on('pagehide', () => {
    window.removeEventListener('resize', syncHeight);
    openingFrameObserver?.disconnect();
    openingFrameObserver = null;
  });
}

$(async () => {
  await errorCatched(async () => {
    await waitGlobalInitialized('Mvu');
    ensureOpeningStatData();
    const app = createApp(App).use(createPinia());
    app.mount('#app');
    adaptMobileOpeningFrame();
    $(window).on('pagehide', () => app.unmount());
    console.info('[开场] 页面加载完成');
  })();
});
